#include <iostream>
#include <locale>
#include <sstream>
#include <string>

int main()
{
    std::istringstream input{"Atlas 120   "};
    input.imbue(std::locale::classic());
    std::string title;
    int pages{};
    if (!(input >> title >> pages)) {
        std::cout << "Malformed record\n";
        return 0;
    }
    input >> std::ws;
    if (!input.eof() || pages < 0) {
        std::cout << "Unexpected record data\n";
        return 0;
    }
    std::ostringstream output;
    output.imbue(std::locale::classic());
    output << title << " has " << pages << " pages";
    std::cout << output.str() << '\n';
}
